import { randomBytes } from '../crypto';
import type { KeyProvider, RawStore } from './types';
import { createMemoryRawStore } from './memory';
import { toBase64, fromBase64 } from '../crypto';

// Persistent key for the session using sessionStorage (not localStorage) to avoid insecure persistence.
let cachedKey: Uint8Array | null = null;

/** Simple key provider that generates a random key once per session and stores it in sessionStorage. */
export function createDeviceKeyProvider(): KeyProvider {
  return {
    async getKey() {
      if (cachedKey) return cachedKey;
      const stored = typeof sessionStorage !== 'undefined' ? sessionStorage.getItem('app.data-key') : null;
      if (stored) {
        cachedKey = fromBase64(stored);
        return cachedKey;
      }
      const key = randomBytes(32); // 256-bit key
      if (typeof sessionStorage !== 'undefined') {
        try {
          sessionStorage.setItem('app.data-key', toBase64(key));
        } catch {}
      }
      cachedKey = key;
      return key;
    },
  };
}

let rawStoreInstance: RawStore | null = null;

/** Return a persistent in‑memory raw store for the whole session. */
export function createDeviceRawStore(): RawStore {
  if (!rawStoreInstance) {
    rawStoreInstance = createMemoryRawStore();
  }
  return rawStoreInstance;
}
"}

