    {
      "severity": "medium",
      "file": "src/components/ui/PrimaryButton.tsx",
      "issue": "Focus‑visible styling is not defined for web. While RN‑Paper provides a ripple on native, there is no custom `:focus-visible` outline (2 dp `theme.colors.outline`) for keyboard users, violating the accessible focus requirement.",
      "fix": "Add a style rule for web that applies a `2dp` outline with the token `theme.colors.outline` when the button receives `:focus-visible`. Ensure the same visual cue appears on all interactive components (SecondaryButton, MiniFAB, ChoiceField, etc.)."
    },
    {
      "severity": "medium",
      "file": "src/components/ui/EmptyState.tsx",
      "issue": "Copy mismatch: the empty‑state description for the Dashboard uses *“Add a receipt or mileage entry to start tracking your finances.”* instead of the exact spec wording *“Add a receipt or mileage entry to start tracking your finances.”* (missing a period) and the primary button label is “Add receipt” (correct) but the icon’s accessibilityLabel is missing.",
      "fix": "Adjust the description to match the spec exactly (including punctuation). Add `accessibilityLabel=\"Add receipt\"` to the primary button’s icon‑only variant if any."
    },
    {
      "severity": "medium",
      "file": "src/components/ui/FABAdd.tsx",
      "issue": "The FAB does not expose a visible focus outline when navigated via keyboard on web, and the mini‑FABs lack explicit `aria-label` attributes, making them hard to discover for screen‑reader users.",
      "fix": "Add `accessibilityLabel` props to both the main FAB (`\"Add entry\"`) and each mini‑FAB (`\"Add receipt\"`, `\"Add mileage\"`). Implement a focus‑visible outline consistent with the design token."
    },
    {
      "severity": "medium",
      "file": "src/components/ui/SettingSwitch.tsx",
      "issue": "Switch components use the default `onColor` and `thumbColor` values instead of the design tokens (`secondary` and `onSecondary`). This introduces ad‑hoc colours that break visual consistency.",
      "fix": "Pass `trackColor={{ false: theme.colors.disabled, true: theme.colors.secondary }}` and `thumbColor={theme.colors.onSecondary}` (or use the Paper `color` prop) to ensure the switch follows the token palette."
    },
    {
      "severity": "medium",
      "file": "src/screens/SettingsScreen.tsx",
      "issue": "Navigation to the Backup flow is only via the Settings list item; the spec requires that every primary action be reachable from any signed‑in screen via the bottom tab bar or FAB. Backup is not available from the Dashboard or Receipts screens.",
      "fix": "Add a shortcut action (e.g., a secondary FAB or a bottom‑tab bar overflow menu) that opens the Backup screen from any primary screen, or expose a contextual menu in the Settings tab that is reachable via a persistent navigation component."
    },
    {
      "severity": "low",
      "file": "src/components/ui/EmptyState.tsx",
      "issue": "The `EmptyState` illustration lacks an `accessibilityLabel` (e.g., \"Empty state illustration\"), which may be announced as a generic image without context.",
      "fix": "Add `accessibilityLabel=\"Empty state illustration\"` to the illustration `Image` component."
    },
    {
      "severity": "low",
      "file": "src/components/ui/ReceiptCard.tsx",
      "issue": "The card’s touchable area does not guarantee the required 44 × 44 dp minimum on web – the container’s padding is only 8 dp, making the clickable area smaller on small screens.",
      "fix": "Wrap the card content in a `Pressable` with `hitSlop={{ top: 18, bottom: 18, left: 18, right: 18 }}` (or ensure the styled wrapper has at least 44 dp height) to meet the touch‑target requirement."
    },
    {
      "severity": "low",
      "file": "src/components/ui/FormField.tsx",
      "issue": "Some `TextInput` fields lack `autoComplete` props (e.g., amount, date). While not required for a local‑first app, adding appropriate autocomplete (numeric, date) improves the experience.",
      "fix": "Add `autoComplete=\"off\"` for amount (numeric) fields, `autoComplete=\"bday\"` or similar for date, and enable `keyboardType=\"numeric\"` where needed."
    }
  ]
}

