{"path": "src/components/ui/ScreenHeader.tsx", "content": "import React from 'react';
import { StyleSheet, View } from 'react-native';
import { Text } from 'react-native-paper';
import { theme, space } from '../../theme';

/** Consistent header used on full‑screen pages (title + optional subtitle). */
export default function ScreenHeader({ title, subtitle }: { title: string; subtitle?: string }) {
  return (
    <View style={styles.container} accessible accessibilityRole="header">
      <Text variant="headlineSmall" style={styles.title} accessibilityRole="header">
        {title}
      </Text>
      {subtitle ? <Text variant="bodyMedium" style={styles.subtitle}>{subtitle}</Text> : null}
    </View>
  );
}

const styles = StyleSheet.create({
  container: { marginBottom: space(2) },
  title: { fontWeight: '600', marginBottom: space(1) },
  subtitle: { color: theme.colors.onSurfaceVariant },
});
"}

{"path": "src/components/ui/ScreenContainer.tsx", "content": "import React from 'react';
import { View, StyleSheet } from 'react-native';
import { space } from '../../theme';

/**
 * Constrains content to a comfortable max width and adds horizontal padding.
 * Used on large viewports to avoid ultra‑wide lines while keeping phone layout.
 */
export default function ScreenContainer({ children }: { children: React.ReactNode }) {
  return <View style={styles.container}>{children}</View>;
}

const styles = StyleSheet.create({
  container: {
    alignSelf: 'center',
    width: '100%',
    maxWidth: 560,
    paddingHorizontal: space(3), // 24dp
  },
});
"}

{"path": "src/screens/BackupPassphraseScreen.tsx", "content": "import React, { useState } from 'react';
import { HelperText } from 'react-native-paper';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { FormField, PrimaryButton, Screen } from '../components/ui';
import { createBackup } from '../lib/backup';
import { utf8 } from '../lib/crypto';
import { saveAndShare } from '../lib/files';
import { getStore } from '../lib/storage';

const MIN_LENGTH = 8;
/**
 * Validate passphrase: at least MIN_LENGTH characters and at least two of the four character classes:
 * uppercase, lowercase, digits, symbols.
 */
function validatePassphrase(p: string): string | null {
  if (p.length < MIN_LENGTH) return `Use at least ${MIN_LENGTH} characters.`;
  const classes = [/[A-Z]/, /[a-z]/, /[0-9]/, /[^A-Za-z0-9]/].filter((re) => re.test(p)).length;
  if (classes < 2) return 'Use at least two character classes (uppercase, lowercase, digit, symbol).';
  return null;
}

export default function BackupPassphraseScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [pass1, setPass1] = useState('');
  const [pass2, setPass2] = useState('');
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);

  const create = async () => {
    const validation = validatePassphrase(pass1);
    if (validation) return setError(validation);
    if (pass1 !== pass2) return setError("The passphrases don't match.");
    setError('');
    setBusy(true);
    try {
      const backup = await createBackup(getStore(), pass1);
      // Share backup asynchronously (fire‑and‑forget)
      saveAndShare(`finance-backup-${new Date().toISOString().slice(0, 10)}.backup`, utf8(backup)).catch(() => {});
      // Navigate to success screen where "Backup ready to share" is displayed
      navigation.navigate('backup_success');
    } catch {
      setError('The backup could not be created. Please try again.');
    } finally {
      setBusy(false);
    }
  };

  // Determine field error for display
  const fieldError = error || (pass1 && pass2 && validatePassphrase(pass1) ? validatePassphrase(pass1) : null);

  // Disable button if busy or validation fails
  const canCreate = !busy && !validatePassphrase(pass1) && pass1 === pass2 && pass1 !== '';

  return (
    <Screen title="Create backup" subtitle="Choose a passphrase to lock the backup file.">
      <FormField
        label="Backup passphrase"
        value={pass1}
        onChangeText={setPass1}
        secureTextEntry
        autoCapitalize="none"
        hint={`At least ${MIN_LENGTH} characters`}
        accessibilityLabel="Backup passphrase"
      />
      <FormField
        label="Confirm passphrase"
        value={pass2}
        onChangeText={setPass2}
        secureTextEntry
        autoCapitalize="none"
        accessibilityLabel="Confirm passphrase"
      />
      {fieldError ? <HelperText type="error">{fieldError}</HelperText> : null}
      <PrimaryButton label="Create backup" onPress={create} loading={busy} disabled={!canCreate} />
    </Screen>
  );
}
"}

