{"path": "src/screens/BackupPassphraseScreen.tsx", "content": "import React, { useState } from 'react';
import { HelperText } from 'react-native-paper';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { FormField, PrimaryButton, Screen } from '../components/ui';
import { createBackup } from '../lib/backup';
import { utf8 } from '../lib/crypto';
import { saveAndShare } from '../lib/files';
import { getStore } from '../lib/storage';

const MIN_LENGTH = 8;
/**
 * Validate passphrase: at least MIN_LENGTH characters and at least three of the four character classes:
 * uppercase, lowercase, digits, symbols.
 */
function validatePassphrase(p: string): string | null {
  if (p.length < MIN_LENGTH) return `Use at least ${MIN_LENGTH} characters.`;
  const classes = [/[A-Z]/, /[a-z]/, /[0-9]/, /[^A-Za-z0-9]/].filter((re) => re.test(p)).length;
  if (classes < 3) return 'Use at least three character classes (uppercase, lowercase, digit, symbol).';
  return null;
}

export default function BackupPassphraseScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [pass1, setPass1] = useState('');
  const [pass2, setPass2] = useState('');
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);

  const create = async () => {
    const validation = validatePassphrase(pass1);
    if (validation) return setError(validation);
    if (pass1 !== pass2) return setError("The passphrases don't match.");
    setError('');
    setBusy(true);
    try {
      const backup = await createBackup(getStore(), pass1);
      // Share backup asynchronously (fire‑and‑forget)
      saveAndShare(`finance-backup-${new Date().toISOString().slice(0, 10)}.backup`, utf8(backup)).catch(() => {});
      navigation.navigate('backup_success');
    } catch {
      setError('The backup could not be created. Please try again.');
    } finally {
      setBusy(false);
    }
  };

  const fieldError = error || (pass1 && pass2 && validatePassphrase(pass1) ? validatePassphrase(pass1) : null);
  const canCreate = !busy && !validatePassphrase(pass1) && pass1 === pass2 && pass1 !== '';

  return (
    <Screen title="Create backup" subtitle="Choose a passphrase to lock the backup file.">
      <FormField
        label="Backup passphrase"
        value={pass1}
        onChangeText={setPass1}
        secureTextEntry
        autoCapitalize="none"
        hint={`At least ${MIN_LENGTH} characters`}
        accessibilityLabel="Backup passphrase"
      />
      <FormField
        label="Confirm passphrase"
        value={pass2}
        onChangeText={setPass2}
        secureTextEntry
        autoCapitalize="none"
        accessibilityLabel="Confirm passphrase"
      />
      {fieldError ? <HelperText type="error">{fieldError}</HelperText> : null}
      <PrimaryButton label="Create backup" onPress={create} loading={busy} disabled={!canCreate} />
    </Screen>
  );
}
"}

{"path": "src/lib/photoPicker.ts", "content": "/** Simple wrapper to pick an image from library or camera using expo-image-picker if available.
 * Dynamically imports the module to avoid static bundler resolution issues in environments
 * where expo-image-picker is not available (e.g., web builds without native support).
 * Enforces a maximum file size of 5 MiB to avoid exhausting device storage.
 */
import * as FileSystem from 'expo-file-system';

export async function pickImageAsync(): Promise<string | undefined> {
  try {
    // Dynamically import to keep TypeScript happy without requiring type declarations.
    const ImagePicker: any = await import('expo-image-picker');
    const { status } = await ImagePicker.requestMediaLibraryPermissionsAsync();
    if (status !== 'granted') {
      return undefined;
    }
    const result = await ImagePicker.launchImageLibraryAsync({
      allowsEditing: true,
      quality: 0.8,
      mediaTypes: ImagePicker.MediaTypeOptions.Images,
    });
    if (!result.cancelled) {
      // Check file size; reject large images (>5 MB).
      const info = await FileSystem.getInfoAsync(result.uri);
      const maxBytes = 5 * 1024 * 1024; // 5 MiB
      if (info.size && info.size > maxBytes) {
        // Too large – could show a toast or simply ignore.
        console.warn('Selected image exceeds size limit of 5 MiB');
        return undefined;
      }
      return result.uri;
    }
  } catch (e) {
    // If the module cannot be loaded or any error occurs, just return undefined.
  }
  return undefined;
}
"}

{"path": "src/screens/ReceiptEntryScreen.tsx", "content": "import React, { useState } from 'react';
import { View } from 'react-native';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { PrimaryButton, Screen, FormField, ChoiceField } from '../components/ui';
import { addReceipt } from '../lib/receiptStore';
import { getStore } from '../lib/storage';
import { Receipt, ReceiptType } from '../lib/models';
import { Snackbar } from 'react-native-paper';
import { setPendingSnack } from '../lib/uiState';
import ReceiptImagePicker from '../components/ui/ReceiptImagePicker';
import { v4 as uuidv4 } from 'uuid';

export default function ReceiptEntryScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [category, setCategory] = useState('');
  const [type, setType] = useState<ReceiptType>('expense');
  const [notes, setNotes] = useState('');
  const [photoUri, setPhotoUri] = useState<string | undefined>(undefined);
  const [error, setError] = useState<string>('');
  const [saving, setSaving] = useState(false);

  const validate = () => {
    if (!amount) return 'Enter a positive amount.';
    const amt = Number(amount);
    if (isNaN(amt) || amt <= 0) return 'Enter a positive amount.';
    // limit to 9 digits and max two decimal places
    if (!/^\d{1,9}(\.\d{1,2})?$/.test(amount)) return 'Amount must have up to 9 digits and 2 decimals.';
    if (!date) return 'Select a date.';
    if (!category) return 'Choose a category.';
    if (!type) return 'Select expense or income.';
    return '';
  };

  const onSave = async () => {
    const err = validate();
    if (err) {
      setError(err);
      return;
    }
    setError('');
    setSaving(true);
    const receipt: Receipt = {
      id: uuidv4(),
      amount: Number(amount),
      date,
      category,
      type,
      notes,
      photoUri,
    };
    try {
      await addReceipt(getStore(), receipt);
      setPendingSnack('Receipt saved');
      navigation.navigate('Main', { screen: 'Dashboard' });
    } catch (e) {
      setError('Unable to save receipt. Please try again.');
    } finally {
      setSaving(false);
    }
  };

  const canSave = !saving && validate() === '';

  return (
    <Screen title="Add receipt">
      <View style={{ gap: 12 }}>
        <ReceiptImagePicker photoUri={photoUri} onChange={setPhotoUri} />
        <FormField label="Amount" value={amount} onChangeText={setAmount} keyboardType="numeric" />
        <FormField label="Date" value={date} onChangeText={setDate} placeholder="YYYY-MM-DD" />
        <FormField label="Category" value={category} onChangeText={setCategory} />
        <ChoiceField<ReceiptType>
          label="Type"
          value={type}
          onChange={setType}
          options={[{ value: 'expense', label: 'Expense' }, { value: 'income', label: 'Income' }]}
        />
        <FormField label="Notes" value={notes} onChangeText={setNotes} multiline />
        {error ? <Snackbar visible={true} onDismiss={() => setError('')} duration={3000}>{error}</Snackbar> : null}
        <PrimaryButton label="Save receipt" onPress={onSave} loading={saving} disabled={!canSave} />
      </View>
    </Screen>
  );
}
"}

